,D.INSTITUTION_CODE institutionCode
FROM RSK_AUTHORIZE_MNG
LEFT JOIN SYS_USER B ON RSK_AUTHORIZE_MNG.USER_NAME = B.USER_NAME LEFT JOIN SYS_DEPARTMENT D ON D.DEPT_CODE = B.DEPT_CODE
ROLE_POS = #{rolePos,jdbcType=VARCHAR}
AND (RSK_AUTHORIZE_MNG.USER_NAME IN
null) OR RSK_AUTHORIZE_MNG.USER_NAME in (
#{item}
